const tasks = items[0].json.results || [];

// Initialiser les compteurs
const stats = {
  total: tasks.length,
  byStatus: {},
  byProject: {},
  byPriority: {},
  blocked: [],
  highPriority: [],
  updatedToday: 0
};

const today = new Date().toISOString().split('T')[0];

// Analyser chaque tâche
tasks.forEach(task => {
  const props = task.properties;

  // Status
  const status = props.Status?.select?.name || 'Unknown';
  stats.byStatus[status] = (stats.byStatus[status] || 0) + 1;

  // Project
  const project = props.Project?.select?.name || 'Unknown';
  stats.byProject[project] = (stats.byProject[project] || 0) + 1;

  // Priority
  const priority = props.Priority?.select?.name;
  if (priority) {
    stats.byPriority[priority] = (stats.byPriority[priority] || 0) + 1;

    // High priority tasks
    if (priority === 'Critical' || priority === 'High') {
      const name = props.Name?.title?.[0]?.plain_text || 'Unnamed';
      const key = props['Jira Key']?.rich_text?.[0]?.plain_text || '';
      const url = props.URL?.url || '';
      stats.highPriority.push({ name, key, url, status });
    }
  }

  // Blocked tasks
  if (status === 'Blocked') {
    const name = props.Name?.title?.[0]?.plain_text || 'Unnamed';
    const key = props['Jira Key']?.rich_text?.[0]?.plain_text || '';
    const assignee = props.Assignee?.rich_text?.[0]?.plain_text || 'Unassigned';
    const url = props.URL?.url || '';
    stats.blocked.push({ name, key, assignee, url });
  }

  // Updated today
  const updated = props.Updated?.date?.start;
  if (updated && updated.startsWith(today)) {
    stats.updatedToday++;
  }
});

return [{ json: stats }];

const stats = items[0].json;
const date = new Date().toLocaleDateString('fr-FR', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

// Construire le rapport HTML
let html = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; color: #333; max-width: 800px; margin: 0 auto; padding: 20px; }
    h1 { color: #2563eb; border-bottom: 3px solid #2563eb; padding-bottom: 10px; }
    h2 { color: #475569; margin-top: 30px; }
    .metric { background: #f1f5f9; padding: 15px; margin: 10px 0; border-radius: 8px; }
    .metric-title { font-weight: bold; color: #64748b; }
    .metric-value { font-size: 24px; color: #1e293b; font-weight: bold; }
    .status-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .alert { background: #fef2f2; border-left: 4px solid #ef4444; padding: 12px; margin: 10px 0; }
    .task-item { padding: 8px; margin: 5px 0; background: #fafafa; border-radius: 4px; }
    .task-link { color: #2563eb; text-decoration: none; }
    table { width: 100%; border-collapse: collapse; margin: 15px 0; }
    th, td { padding: 10px; text-align: left; border-bottom: 1px solid #e2e8f0; }
    th { background: #f8fafc; font-weight: bold; }
  </style>
</head>
<body>
  <h1>📊 Rapport Quotidien des Tâches</h1>
  <p style="color: #64748b;">${date}</p>

  <div class="metric">
    <div class="metric-title">Total des tâches actives</div>
    <div class="metric-value">${stats.total}</div>
  </div>

  <div class="metric">
    <div class="metric-title">Mises à jour aujourd'hui</div>
    <div class="metric-value">${stats.updatedToday}</div>
  </div>
`;

// Par Projet
html += '<h2>📦 Répartition par Projet</h2><table><tr><th>Projet</th><th>Nombre de tâches</th></tr>';
for (const [project, count] of Object.entries(stats.byProject)) {
  html += `<tr><td>${project}</td><td><strong>${count}</strong></td></tr>`;
}
html += '</table>';

// Par Statut
html += '<h2>🎯 Répartition par Statut</h2><div class="status-grid">';
for (const [status, count] of Object.entries(stats.byStatus)) {
  html += `<div class="metric"><div class="metric-title">${status}</div><div class="metric-value">${count}</div></div>`;
}
html += '</div>';

// Priorités
if (Object.keys(stats.byPriority).length > 0) {
  html += '<h2>⚡ Tâches Priorisées</h2><table><tr><th>Priorité</th><th>Nombre</th></tr>';
  for (const [priority, count] of Object.entries(stats.byPriority)) {
    html += `<tr><td>${priority}</td><td><strong>${count}</strong></td></tr>`;
  }
  html += '</table>';
}

// Bloqueurs
if (stats.blocked.length > 0) {
  html += `<h2>🚨 Tâches Bloquées (${stats.blocked.length})</h2>`;
  stats.blocked.forEach(task => {
    html += `<div class="alert"><strong>${task.name}</strong><br/>`;
    html += `<small>${task.key} • Assigné à: ${task.assignee}</small><br/>`;
    if (task.url) html += `<a href="${task.url}" class="task-link">Voir dans Jira →</a>`;
    html += `</div>`;
  });
}

// High Priority
if (stats.highPriority.length > 0) {
  html += `<h2>🔥 Tâches Haute Priorité (${stats.highPriority.length})</h2>`;
  stats.highPriority.slice(0, 10).forEach(task => {
    html += `<div class="task-item"><strong>${task.name}</strong> • <span style="color: #64748b;">${task.status}</span><br/>`;
    html += `<small>${task.key}</small>`;
    if (task.url) html += ` • <a href="${task.url}" class="task-link">Voir →</a>`;
    html += `</div>`;
  });
}

html += '</body></html>';

return [{ 
  json: { 
    html,
    subject: `📊 Rapport Quotidien - ${stats.total} tâches actives`,
    summary: `${stats.total} tâches • ${stats.blocked.length} bloquées • ${stats.updatedToday} mises à jour aujourd'hui`
  } 
}];

